import{z as o,x as B,o as i,c as g,q as l,j as r,D as n,d as e,s as A,S as t,b as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"Yang–Zhang 估计量","description":"","frontmatter":{"title":"Yang–Zhang 估计量","date":"2026-09-27T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/yang-zhang.md","filePath":"quant/yang-zhang.md","lastUpdated":1791063341000}'),d={name:"quant/yang-zhang.md"};function _(m,a,u,p,h,C){const s=B("Mermaid");return i(),g("div",null,[a[2]||(a[2]=l('<h1 id="yang–zhang-估计量" tabindex="-1">Yang–Zhang 估计量 <a class="header-anchor" href="#yang–zhang-估计量" aria-label="Permalink to &quot;Yang–Zhang 估计量&quot;">​</a></h1><div class="epigraph"><p>把日方差显式拆成隔夜与盘内两段，盘内用对漂移无偏的交叉乘积，再按最小方差加权合并——跳空与漂移两根刺一起拔。</p><footer>—— 据 Yang and Zhang, Journal of Business, 2000</footer></div><p><a href="/quant/garman-klass">上一课</a>的效率以「无漂移、开盘无跳空」为前提，真实股票两条全破。Yang–Zhang 把日方差显式拆段：隔夜段用收盘到开盘，盘内段用对漂移无偏的 Rogers–Satchell 交叉乘积，再按最小方差权重合并。微观噪声是它剩下的软肋，怎么压决定了它该在什么频率上跑。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>三个缺口逐个点名。其一，漂移：close-to-close 与 GK 的估计量在漂移非零时都有偏，持仓周期越长偏差越显眼。其二，隔夜跳空：只用盘内 OHLC 的公式（RS 一族）对 gap 完全失明，隔夜方差整段丢失。其三，微观噪声：任何用收盘价差平方的项都随 bid-ounce 膨胀。Yang–Zhang 的目标是同时对漂移与跳空无偏，再把噪声从最窄的门放进来。本课写拆段、加权与失效方向，不展开 YZ* 变体的推导。</p><p><span class="marginnote">术语翻译：拆段即把「昨日收盘到今日收盘」切成「昨日收盘到今日开盘」（隔夜段 \\(o_i\\)）与「今日开盘到今日收盘」（盘内段 \\(c_i\\)）两张账。Rogers–Satchell 是只用盘内四价的交叉乘积估计量，构造上对非零漂移无偏——代价是看不见隔夜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(o_i=\\ln(O_i/C_{i-1})\\)、\\(u_i=\\ln(H_i/O_i)\\)、\\(d_i=\\ln(L_i/O_i)\\)、\\(c_i=\\ln(C_i/O_i)\\)。三个分量：</p> \\[\\sigma_O^2=\\frac{1}{n-1}\\sum o_i^2,\\quad \\sigma_C^2=\\frac{1}{n-1}\\sum c_i^2,\\quad \\sigma_{RS}^2=\\frac{1}{n}\\sum\\left[u_i(u_i-c_i)+d_i(d_i-c_i)\\right] \\]<p>合并按 \\(\\sigma_{YZ}^2=\\sigma_O^2+k\\,\\sigma_C^2+(1-k)\\,\\sigma_{RS}^2\\)，权重 \\(k=\\dfrac{0.34}{1.34+(n+1)/(n-1)}\\)。<span class="marginnote">数字实例：\\(n=10\\) 时 \\((n+1)/(n-1)\\approx1.222\\)，\\(k\\approx0.133\\)；\\(n=60\\) 时 \\(k\\approx0.143\\)——窗口再长 \\(k\\) 也爬不过 0.15，最怕噪声的 \\(\\sigma_C^2\\) 永远只拿小头。近理想条件下 YZ 对 close-to-close 的效率约 8 倍，倍数随噪声浮动，别当常数。</span></p>',10)),(i(),r(t,null,{default:n(()=>[A(s,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20DATA%5B%22%E5%8F%96%20n%20%E6%97%A5%20OHLC%22%5D%20--%3E%20SEG%5B%22%E6%8B%86%E9%9A%94%E5%A4%9C%E6%AE%B5%E4%B8%8E%E7%9B%98%E5%86%85%E6%AE%B5%22%5D%0A%20%20SEG%20--%3E%20SO%5B%22%E7%AE%97%E9%9A%94%E5%A4%9C%E6%96%B9%E5%B7%AE%20sigmaO%22%5D%0A%20%20SEG%20--%3E%20SC%5B%22%E7%AE%97%E5%BC%80%E6%94%B6%E6%96%B9%E5%B7%AE%20sigmaC%22%5D%0A%20%20SEG%20--%3E%20SRS%5B%22%E7%AE%97%20Rogers%E2%80%93Satchell%20%E4%BA%A4%E5%8F%89%E4%B9%98%E7%A7%AF%22%5D%0A%20%20SO%20--%3E%20MIX%5B%22%E6%8C%89%20k%20%E5%8A%A0%E6%9D%83%E5%90%88%E5%B9%B6%E6%88%90%20YZ%22%5D%0A%20%20SC%20--%3E%20MIX%0A%20%20SRS%20--%3E%20MIX%0A%20%20MIX%20--%3E%20ANN%5B%22%E5%B9%B4%E5%8C%96%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("无偏性来自构造：交叉乘积 \\(u(u-c)\\) 里漂移项在展开后相消，所以 \\(\\sigma_{RS}^2\\) 不怕非零漂移；隔夜段显式入账，gap 方差不再失踪；合并权重由最小方差解给出。噪声下的行为更微妙：\\(k\\) 压小让 bid-ounce 只从 \\(\\sigma_C^2\\) 一条窄门进来——结果是方差上升而偏差近似不动，这正是小权重的用意。"),E("span",{class:"marginnote"},"直觉类比：YZ 给一天波动装两块电表——过夜待机表和日内用电表；日内表最容易被接线噪声干扰，于是合并时只给它约 13% 的权重，而不是平分。")],-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"常见误区：以为 YZ 万能。错在把噪声与跳跃混为一谈——它治隔夜与漂移，bar 内 bid-ounce 只是压制不是治愈；财报瞬间的离散跳会把所有 OHLC 估计量一起打穿，YZ 没有豁免权。")],-1)),(i(),r(t,null,{default:n(()=>[A(s,{id:"mermaid-36",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22%E8%A6%81%E4%BC%B0%E5%93%AA%E6%AE%B5%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20Q1%7B%22%E9%9A%94%E5%A4%9C%E8%B7%B3%E7%A9%BA%E9%87%8D%E8%A6%81%E5%90%97%22%7D%0A%20%20Q1%20--%3E%7C%22%E9%87%8D%E8%A6%81%22%7C%20YZ%5B%22YZ%EF%BC%9A%E9%9A%94%E5%A4%9C%E6%AE%B5%E6%98%BE%E5%BC%8F%E5%85%A5%E8%B4%A6%22%5D%0A%20%20Q1%20--%3E%7C%22%E5%8F%AF%E5%BF%BD%E7%95%A5%22%7C%20Q2%7B%22%E6%BC%82%E7%A7%BB%E9%9D%9E%E9%9B%B6%E5%90%97%22%7D%0A%20%20Q2%20--%3E%7C%22%E6%98%AF%22%7C%20RS%5B%22RS%EF%BC%9A%E5%AF%B9%E6%BC%82%E7%A7%BB%E6%97%A0%E5%81%8F%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20Q2%20--%3E%7C%22%E5%90%A6%22%7C%20GK%5B%22GK%20%E8%B6%B3%E5%A4%9F%EF%BC%9A%E6%95%88%E7%8E%87%E7%95%A5%E9%AB%98%22%5D%0A%20%20YZ%20--%3E%20Q3%7B%22%E5%BE%AE%E8%A7%82%E5%99%AA%E5%A3%B0%E5%A4%A7%E5%90%97%22%7D%0A%20%20Q3%20--%3E%7C%22%E5%A4%A7%22%7C%20SUB%5B%22%E9%99%8D%E9%A2%91%E5%90%88%E6%88%90%E6%88%96%E4%B8%8A%20YZ*%22%5D%0A%20%20Q3%20--%3E%7C%22%E5%B0%8F%22%7C%20DAY%5B%22%E7%9B%B4%E6%8E%A5%E6%97%A5%E9%A2%91%20YZ%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不治跳跃：离散跳之日，五类估计量集体失真，事后剔除事件日比换公式诚实。停牌与集合竞价 bar 的高低差不可信，照单全收会把噪声当波动。实现细节有坑：\\(\\sigma_O^2\\) 用 \\(n-1\\)、\\(\\sigma_{RS}^2\\) 用 \\(n\\) 是原文献口径，混用会引入微小不一致。日波动作为输入，一侧对照隐含口径归 <a href="/quant/vol-surface">波动率曲面</a>，一侧进 <a href="/quant/risk-budgeting">风险预算</a> 的限额。至此本单元收束：粒子滤波与无迹卡尔曼管状态、OU 管动力学、Garman–Klass 与 Yang–Zhang 管测量——「估得准」在量化里的三个切面，拼图到此合拢。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>YZ 拆段加权：隔夜段补 gap、RS 段抗漂移、小权重 \\(\\sigma_C^2\\) 压噪声。</li><li>\\(k\\) 约 0.13–0.15，由最小方差解给出，不随手调。</li><li>无偏覆盖漂移与跳空；噪声只推高方差；离散跳没有豁免。</li><li>测量口径与状态估计、动力学参数互为上下游，五个 slug 拼一张图。</li><li>出处：Yang and Zhang, <em>Journal of Business</em>, 2000；Rogers, Satchell and Yoon, 1994；Molnár, 2012 对照。</li></ul>',4))])}const f=o(d,[["render",_]]);export{S as __pageData,f as default};
